import { finUUID } from './env';
import LocalStorageKey from './local-storage-key';

export const setItem = (key: LocalStorageKey, value: string) => {
    localStorage.setItem(`${finUUID}-${key}`, value);
};
export const getItem = (key: LocalStorageKey) => {
    return localStorage.getItem(`${finUUID}-${key}`);
};
export const removeItem = (key: LocalStorageKey) => {
    return localStorage.removeItem(`${finUUID}-${key}`);
};

export const createNamespacedLocalStorage = <TKey extends string>(
    namespace: string
): Pick<Storage, 'setItem' | 'getItem' | 'removeItem'> => ({
    setItem: (key: TKey, value: string) => {
        localStorage.setItem(`${namespace}-${key}`, value);
    },
    getItem: (key: TKey) => {
        return localStorage.getItem(`${namespace}-${key}`);
    },
    removeItem: (key: TKey) => {
        return localStorage.removeItem(`${namespace}-${key}`);
    }
});
