import { currentOFIdentity } from '@common/utils/window';

import {
    CopyPagePayload,
    HandleSaveModalOnPageClosePayload,
    Page,
    SaveModalOnPageCloseResult,
    ShouldPageClosePayload,
    ShouldPageCloseResult
} from '@common/api/pages/shapes';
import { getBrowserChannelClient, WorkspacePlatformChannelAction } from '@common/api/protocol/workspace-platform';

import { shouldWindowClose } from '@client-platform/api/pages';

import { HandlePageChangesPayload, ModifiedPageState } from '@client-platform/shapes';

export const requestPageSaveModalDecision = async (
    req: HandleSaveModalOnPageClosePayload
): Promise<SaveModalOnPageCloseResult> => {
    const client = await getBrowserChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.HandleSaveModalOnPageClose, req);
};

export const requestShouldPageClose = async (req: ShouldPageClosePayload): Promise<ShouldPageCloseResult> => {
    const client = await getBrowserChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.ShouldPageClose, req);
};

export const requestShouldWindowClose = async (
    payload: Parameters<typeof shouldWindowClose>[0]
): ReturnType<typeof shouldWindowClose> => {
    const client = await getBrowserChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.ShouldWindowClose, payload);
};

export const copyPage = async (req: CopyPagePayload): Promise<Page> => {
    const client = await getBrowserChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.CopyPage, req);
};

export const requestPageChangesDecision = async (req: HandlePageChangesPayload): Promise<ModifiedPageState> => {
    const client = await getBrowserChannelClient(currentOFIdentity);
    return client.dispatch(WorkspacePlatformChannelAction.HandlePageChanges, req);
};
